use std::{env,fs};use wasmc_data_expr_component::{Lib,wasmtime};use wasmc_data_expr_component::wasmc::data_core::types::{Field,DataType,Column,BatchSnapshot};use wasmc_data_expr_component::exports::wasmc::data_expr::expr::{Program,Node};use wasmtime::{Engine,Store};use wasmtime::component::{Component,Linker};
fn main(){let args:Vec<_>=env::args().collect();let engine=Engine::default();let component=Component::new(&engine,fs::read(&args[1]).unwrap()).unwrap();let mut store=Store::new(&engine,());let lib=Lib::instantiate(&mut store,&component,&Linker::new(&engine)).unwrap();let expr=lib.wasmc_data_expr_expr();for n in [8,1048577,3145728,11]{let batch=BatchSnapshot{rows:1,fields:vec![Field{name:"value".into(),data_type:DataType::Utf8,nullable:false}],columns:vec![Column::Utf8Column(vec![Some("x".repeat(n))])]};let result=expr.call_evaluate(&mut store,&batch,&Program{nodes:vec![Node::Column(0)],root:0}).unwrap().unwrap();match result{Column::Utf8Column(v)=>assert_eq!(v[0].as_ref().unwrap().len(),n),_=>panic!("unexpected column")};}println!("{{\"accepted\":true,\"engine\":\"wasmtime-component\",\"largest_input\":3145728,\"same_instance_new_inputs\":true}}");}
